// REVIEW_GROUPS_END

for (const style of STYLE_DATA) {
  const review = STRICT_STYLE_EDITORIAL_REVIEWS[style.id];
  if (!review) continue;
  if (!Array.isArray(review.en) || review.en.length !== 6) throw new Error(`${style.id}: editorial review requires six English genes`);
  const genesZh = review.zh || style.visualGenes.map((gene) => gene.zh);
  if (genesZh.length !== 6) throw new Error(`${style.id}: editorial review requires six Chinese genes`);
  style.summary = review.summary;
  if (review.period) style.period = review.period;
  if (Number.isFinite(review.year)) style.year = review.year;
  if (review.region) style.region = review.region;
  style.visualGenes = genesZh.map((zh, index) => ({ zh, en: review.en[index] }));
  style.recognition = style.visualGenes.slice(0, 5).map((gene) => gene.zh).join("；") + "。";
  style.genes.composition = [genesZh[0]];
  style.genes.form = [genesZh[1]];
  style.genes.color = [genesZh[2]];
  style.genes.type = [genesZh[5]];
  style.genes.texture = [genesZh[4]];
  style.editorialReviewed = true;
}

// The original retained catalog was already hand-written. This pass records its
// factual review without forcing styles with different visual mechanisms into a
// fixed gene count.
const STRICT_BASE_STYLE_IDS = new Set([
  "ancient-egyptian", "classical-greek", "byzantine", "gothic", "renaissance", "mannerism", "baroque", "rococo", "neoclassicism", "romanticism", "realism", "pre-raphaelite", "impressionism", "post-impressionism", "symbolism", "arts-crafts", "art-nouveau", "fauvism", "expressionism", "cubism", "futurism", "dada", "constructivism", "suprematism", "de-stijl", "bauhaus", "surrealism", "art-deco", "abstract-expressionism", "color-field", "pop-art", "op-art", "minimalism", "neo-expressionism", "photorealism", "postmodernism", "lowbrow", "psychedelic", "ink-wash", "gongbi", "ukiyo-e", "rinpa", "nihonga", "superflat", "korean-minhwa", "persian-miniature", "mughal-miniature", "madhubani", "islamic-geometry", "thangka", "mexican-muralism", "afrofuturism", "swiss", "mid-century-modern", "scandinavian-modern", "streamline-moderne", "atomic-age", "new-wave-typography", "memphis", "punk-visual", "grunge-design", "architectural-brutalism", "brutalism", "flat-design", "skeuomorphism", "acid-graphics", "glitch-art", "retrofuturism", "synthwave", "vaporwave", "y2k", "gothic-subculture", "film-noir", "maximalism", "neo-futurism", "biomorphic", "neo-pop", "naive-art", "blue-green-landscape", "song-court-painting", "baimiao"
]);

const STRICT_BASE_STYLE_FACT_REVIEWS = {
  "ink-wash": {
    period: "约8世纪至今",
    year: 1000,
    summary: "水墨画自唐宋以来以墨的浓淡干湿、书写性用笔、散点游观和主动留白建立空间与气韵；这里指可跨题材迁移的水墨视觉系统，不把文人身份或传统题材强加给用户主体。"
  },
  "gongbi": {
    period: "约7世纪至今",
    year: 1000,
    summary: "工笔画在唐宋时期形成成熟范式，以精谨线描、分层罩染、矿物设色和受控边缘塑造清晰形体；核心是制作方法与画面秩序，不限定题材。"
  },
  "ukiyo-e": {
    period: "约1603–1868年",
    year: 1770,
    summary: "浮世绘是江户时代的日本城市木版画与绘画体系，以大胆裁切、压缩空间、明确墨线和多版套色形成高辨识度平面语言。"
  },
  "rinpa": {
    period: "17世纪初至今",
    year: 1700,
    summary: "琳派自17世纪初形成并延续复兴，以跨屏构图、偏置重心、金银地、矿物色、节奏化形体和湿中叠染构成日本装饰绘画传统。"
  },
  "korean-minhwa": {
    period: "约18–20世纪",
    year: 1850,
    summary: "朝鲜民画在朝鲜王朝后期广泛发展，以正面平面结构、反常透视、鲜明矿物色和程式化吉祥图式形成自由而直接的民间绘画语言。"
  },
  "islamic-geometry": {
    period: "约8世纪至今",
    year: 1200,
    summary: "伊斯兰几何装饰以尺规构造、放射对称、星形多边形、互锁线带和可无限延展的镶嵌建立非中心秩序，广泛跨越建筑、手抄本与工艺媒介。"
  },
  "afrofuturism": {
    period: "约1960年代至今",
    year: 1993,
    summary: "非洲未来主义以前现代非洲视觉传统、黑人历史、科技与推想叙事重构未来；该术语由马克·德里于1993年提出，但相关视觉实践可追溯至20世纪中后期。"
  },
  "neo-futurism": {
    period: "约1960年代至今",
    year: 2000,
    summary: "新未来主义自20世纪后期在建筑与设计中发展，以连续流线、轻质结构、参数化曲面和技术乐观主义表达面向未来的动态空间。"
  }
};

const STRICT_BASE_STYLE_GENE_REVISIONS = {
  "acid-graphics": {
    replace: {
      "数字噪点与极端压缩字体": [
        "超窄、横向拉伸或纵向堆叠的极端展示字体",
        "extremely condensed, horizontally stretched, or vertically stacked display typography"
      ]
    },
    add: [
      "数字噪点、扫描纹与压缩伪影形成表面干扰",
      "digital noise, scan texture, and compression artifacts forming surface interference"
    ]
  }
};

for (const style of STYLE_DATA) {
  if (!STRICT_BASE_STYLE_IDS.has(style.id)) continue;
  const facts = STRICT_BASE_STYLE_FACT_REVIEWS[style.id];
  if (facts) {
    style.summary = facts.summary;
    if (facts.period) style.period = facts.period;
    if (Number.isFinite(facts.year)) style.year = facts.year;
  }

  const geneReview = STRICT_BASE_STYLE_GENE_REVISIONS[style.id];
  if (geneReview) {
    for (const [sourceZh, replacement] of Object.entries(geneReview.replace || {})) {
      const index = style.visualGenes.findIndex((gene) => gene.zh === sourceZh);
      if (index < 0) throw new Error(`${style.id}: base gene review could not find ${sourceZh}`);
      style.visualGenes[index] = { zh: replacement[0], en: replacement[1] };
    }
    if (geneReview.add) style.visualGenes.push({ zh: geneReview.add[0], en: geneReview.add[1] });
  }

  const genesZh = style.visualGenes.map((gene) => gene.zh);
  style.recognition = genesZh.slice(0, 5).join("；") + "。";
  style.genes.composition = [genesZh[0]];
  style.genes.form = [genesZh[1]];
  style.genes.color = [genesZh[2]];
  style.genes.type = [genesZh[5]];
  style.genes.texture = [genesZh[4]];
  style.editorialReviewed = true;
}
